export const SELECTION_KINDS = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type Selection =
  | Readonly<{ kind: typeof SELECTION_KINDS.closed }>
  | Readonly<{ kind: typeof SELECTION_KINDS.one; index: number }>
  | Readonly<{ kind: typeof SELECTION_KINDS.mismatch; first: number; second: number; remainingMs: number }>;
export const CLOSED_SELECTION: Selection = Object.freeze({ kind: SELECTION_KINDS.closed });
export type GameState = Readonly<{
  board: Board;
  deck: readonly number[];
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return {
    board, deck: generateDeck(board), matched: [], selection: CLOSED_SELECTION,
    moves: 0, elapsedMs: 0, started: false,
  };
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

export function isRevealed(state: GameState, index: number): boolean {
  if (state.matched.includes(index)) return true;
  switch (state.selection.kind) {
    case 'closed': return false;
    case 'one': return state.selection.index === index;
    case 'mismatch': return state.selection.first === index || state.selection.second === index;
  }
}
export const BOARD_VERSION = 'np1';
export const SUPPORTED_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type BoardSize = (typeof SUPPORTED_SIZES)[number];
export const MAX_SEED = 2147483646;
export type Board = Readonly<{ code: string; size: BoardSize; seed: number }>;

export function isBoardSize(value: unknown): value is BoardSize {
  return SUPPORTED_SIZES.some((size) => size === value);
}

export function parseBoardCode(text: string): Board | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9]\d*)$/.exec(text);
  if (!match || match[0] !== text) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code: text, size, seed });
}

import type { Board } from './boardCode.ts';

const MODULUS = 2147483647;
const GENERATOR_RANGE = MODULUS - 1;
export function parkMiller(state: number): number {
  // The largest product is below 2^53, so integer arithmetic is exact.
  return (state * 16807) % MODULUS;
}

export function generateDeck(board: Board): readonly number[] {
  const deck = Array.from({ length: board.size ** 2 }, (_, index) => Math.floor(index / 2));
  let randomState = board.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const bound = index + 1;
    const limit = Math.floor(GENERATOR_RANGE / bound) * bound;
    let value: number;
    do {
      randomState = parkMiller(randomState);
      value = randomState - 1;
    } while (value >= limit);
    const otherIndex = value % bound;
    const current = deck[index];
    const other = deck[otherIndex];
    if (current === undefined || other === undefined) throw new Error('Invalid deck position');
    deck[index] = other;
    deck[otherIndex] = current;
  }
  return Object.freeze(deck);
}
