    expect(run({ ...replay, actions, endMs: 1800 })?.elapsedMs).toBe(800);
    expect(run({ ...replay, actions: [], endMs: Number.MAX_SAFE_INTEGER })?.elapsedMs).toBe(0);
  });
  it('resolves a mismatch exactly before a boundary activation', () => {
