import { useCallback, useRef, useState } from 'react';
import { activateCard } from '../activateCard.ts';
import { advanceGame } from '../advanceGame.ts';
import type { BoardSize } from '../boardCode.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { createGame, isWon } from '../state.ts';
import type { GameState } from '../state.ts';
import { newDeal } from './newDeal.ts';
import { readPreferences, writePreferences } from './storage.ts';
import type { Preferences } from './storage.ts';
import { turnAnnouncement } from './turnAnnouncement.ts';
import { useSessionClock } from './useSessionClock.ts';

type Announcement = Readonly<{ id: number; text: string }>;
type Session = Readonly<{
  game: GameState; dealId: number; paused: boolean; celebrate: boolean;
  preferences: Preferences; announcement: Announcement;
}>;
function initialSession(): Session {
  const preferences = readPreferences();
  return { game: newDeal(preferences.size), preferences, dealId: 0,
    paused: false, celebrate: false, announcement: { id: 0, text: '' } };
}

export function useGameSession() {
  const [session, setSession] = useState(initialSession);
  const current = useRef(session);
  const anchor = useRef(performance.now());
  const visible = useRef(document.visibilityState !== 'hidden');
  const commit = useCallback((next: Session) => {
    current.current = next;
    setSession(next);
  }, []);
  const settle = useCallback((expectedDeal?: number) => {
    const before = current.current;
    if (expectedDeal !== undefined && expectedDeal !== before.dealId) return;
    const now = performance.now();
    const elapsed = now - anchor.current;
    anchor.current = now;
    if (before.paused || !visible.current) return;
    const game = advanceGame(before.game, elapsed);
    if (game !== before.game) commit({ ...before, game });
  }, [commit]);
  const setVisible = useCallback((shown: boolean) => { visible.current = shown; }, []);
  const delay = useCallback(() => {
    const selection = current.current.game.selection;
    return selection.kind === 'mismatch' ? Math.min(100, selection.remainingMs) : 100;
  }, []);
  useSessionClock({ dealId: session.dealId, running: session.game.started
    && !session.paused && !isWon(session.game), settle, setVisible, delay });

  function announce(text: string): Announcement {
    return { id: current.current.announcement.id + 1, text };
  }
  function replace(game: GameState, paused = false, message = '') {
    const before = current.current;
    anchor.current = performance.now();
    const preferences = { ...before.preferences, size: game.board.size };
    writePreferences(preferences);
    commit({ ...before, game, preferences, dealId: before.dealId + 1,
      paused, celebrate: false, announcement: announce(message) });
  }
  function activate(index: number) {
    settle();
    const before = current.current;
    if (before.paused) return;
    const game = activateCard(before.game, index);
    if (game === before.game) return;
    const message = turnAnnouncement(before.game, game);
    let preferences = before.preferences;
    const won = isWon(game);
    if (won) {
      const previous = preferences.best[game.board.size];
      if (previous === undefined || game.moves < previous) {
        preferences = { ...preferences, best: { ...preferences.best, [game.board.size]: game.moves } };
        writePreferences(preferences);
      }
    }
    commit({ ...before, game, preferences, celebrate: won,
      announcement: message ? announce(message) : before.announcement });
  }
  function loadBoard(draft: string): string {
    const game = createGame(draft.trim());
    if (!game) {
      commit({ ...current.current, announcement: announce('Invalid board code.') });
      return 'Invalid board code.';
    }
    replace(game, false, 'Loaded board.');
    return 'Loaded board.';
  }
  function loadSnapshot(draft: string): string {
    const game = decodeSnapshot(draft);
    if (!game) {
      commit({ ...current.current, announcement: announce('Invalid snapshot.') });
      return 'Invalid snapshot.';
    }
    const message = isWon(game) ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.';
    replace(game, !isWon(game), message);
    return message;
  }
  function exportSnapshot(): string {
    settle();
    return encodeSnapshot(current.current.game);
  }
  function resume() {
    anchor.current = performance.now();
    commit({ ...current.current, paused: false });
  }
  function restart() {
    const game = createGame(current.current.game.board.code);
    if (game) replace(game);
  }
  function startNew(size: BoardSize = current.current.game.board.size) {
    replace(newDeal(size, current.current.game.board.code));
  }
  return { ...session, activate, loadBoard, loadSnapshot, exportSnapshot, resume, restart, startNew };
}
import { MAX_MOVES } from '../activateCard.ts';
import { isBoardSize, SUPPORTED_SIZES } from '../boardCode.ts';
import type { BoardSize } from '../boardCode.ts';
import { isRecord, isSafeInteger } from '../formatInput.ts';

export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export type BestScores = Readonly<Partial<Record<BoardSize, number>>>;
export type Preferences = Readonly<{ size: BoardSize; best: BestScores }>;
export type PreferenceStorage = Pick<Storage, 'getItem' | 'setItem'>;

function browserStorage(): PreferenceStorage | null {
  try { return window.localStorage; } catch { return null; }
}

export function readPreferences(storage = browserStorage()): Preferences {
  const fallback: Preferences = { size: 4, best: {} };
  try {
    const text = storage?.getItem(PREFERENCES_KEY);
    if (!text) return fallback;
    const value: unknown = JSON.parse(text);
    if (!isRecord(value)) return fallback;
    const best: Partial<Record<BoardSize, number>> = {};
    if (isRecord(value.best)) {
      for (const size of SUPPORTED_SIZES) {
        const score = value.best[String(size)];
        if (isSafeInteger(score, MAX_MOVES)) best[size] = score;
      }
    }
    return { size: isBoardSize(value.size) ? value.size : 4, best };
  } catch { return fallback; }
}

export function writePreferences(value: Preferences, storage = browserStorage()): void {
  try { storage?.setItem(PREFERENCES_KEY, JSON.stringify(value)); } catch { /* Play stays in memory. */ }
}

import { useEffect } from 'react';

type ClockOptions = Readonly<{
  dealId: number;
  running: boolean;
  settle: (expectedDeal?: number) => void;
  setVisible: (visible: boolean) => void;
  delay: () => number;
}>;

export function useSessionClock({ dealId, running, settle, setVisible, delay }: ClockOptions): void {
  useEffect(() => {
    let disposed = false;
    let timer: number | undefined;
    function schedule() {
      if (!disposed && running && document.visibilityState !== 'hidden') {
        timer = window.setTimeout(tick, delay());
      }
    }
    function tick() {
      if (disposed) return;
      settle(dealId);
      schedule();
    }
    function onVisibility() {
      if (disposed) return;
      settle(dealId);
      setVisible(document.visibilityState !== 'hidden');
      if (timer !== undefined) window.clearTimeout(timer);
      schedule();
    }
    document.addEventListener('visibilitychange', onVisibility);
    schedule();
    return () => {
      disposed = true;
      if (timer !== undefined) window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  }, [dealId, running, settle, setVisible, delay]);
}
import { MAX_SEED } from '../boardCode.ts';
import type { BoardSize } from '../boardCode.ts';
import { createGame } from '../state.ts';
import type { GameState } from '../state.ts';

export function newDeal(size: BoardSize, previousCode?: string): GameState {
  const random = new Uint32Array(1);
  let value: number;
  if (globalThis.crypto?.getRandomValues) {
    globalThis.crypto.getRandomValues(random);
    value = random[0] ?? 0;
  } else value = Math.floor(Math.random() * MAX_SEED);
  let seed = value % MAX_SEED + 1;
  if (`np1-${size}-${seed}` === previousCode) seed = seed % MAX_SEED + 1;
  const game = createGame(`np1-${size}-${seed}`);
  if (!game) throw new Error('Unable to create supported deal');
  return game;
}
import { formatTime } from '../advanceGame.ts';
import { isWon, pairCount } from '../state.ts';
import type { GameState } from '../state.ts';

export function turnAnnouncement(before: GameState, after: GameState): string | null {
  if (before === after || before.selection.kind !== 'one') return null;
  if (after.selection.kind === 'mismatch') return 'No match. Cards close after a short pause.';
  if (pairCount(after) === pairCount(before)) return null;
  if (isWon(after)) {
    return `Pair found. All pairs found in ${after.moves} moves and ${formatTime(after.elapsedMs)}.`;
  }
  const pairs = pairCount(after);
  return `Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`;
}

