export type BoardHandle = Readonly<{ focusRemembered: () => void }>;
type BoardProps = Readonly<{
  game: GameState; paused: boolean; onActivate: (index: number) => void; ref?: Ref<BoardHandle>;
}>;
type BoardStyle = CSSProperties & Readonly<{ '--columns': number }>;

export function Board({ game, paused, onActivate, ref }: BoardProps) {
  const [tabStop, setTabStop] = useState(0);
  const board = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => ({
    focusRemembered() { board.current?.querySelector<HTMLButtonElement>('button[tabindex="0"]')?.focus(); },
  }), []);
  function focus(index: number) {
    board.current?.querySelectorAll('button').item(index)?.focus();
  }
  function keyDown(index: number, event: KeyboardEvent<HTMLButtonElement>) {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const destination = moveFocus(index, game.board.size, event.key);
    if (destination !== null) {
      event.preventDefault();
      focus(destination);
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      onActivate(index);
    }
  }
  const style: BoardStyle = { '--columns': game.board.size };
  return <div className="board-scroll" aria-label="Card board" role="group">
    <div className="board" ref={board} style={style}>
      {game.deck.map((face, index) => <Card key={index} index={index} size={game.board.size} face={face}
        revealed={isRevealed(game, index)} matched={game.matched.includes(index)}
        blocked={paused || game.selection.kind === 'mismatch'} tabStop={index === tabStop}
        onActivate={() => onActivate(index)} onKeyDown={(event) => keyDown(index, event)}
        onFocus={(button) => {
          setTabStop(index);
          button.scrollIntoView({ block: 'nearest', inline: 'nearest' });
        }} />)}
    </div>
  </div>;
}

import { faceIdentity } from './faceIdentity.ts';

type CardFaceProps = Readonly<{ id: number }>;

export function CardFace({ id }: CardFaceProps) {
  const face = faceIdentity(id);
  const paint = { fill: face.fill === 'solid' ? face.color : 'none',
    stroke: face.fill === 'outline' ? face.color : 'none', strokeWidth: 5, strokeLinejoin: 'round' } as const;
  function shape() {
    switch (face.shape) {
      case 'circle': return <circle cx="50" cy="50" r="25" {...paint} />;
      case 'square': return <rect x="25" y="25" width="50" height="50" {...paint} />;
      case 'triangle': return <polygon points="50,25 75,75 25,75" {...paint} />;
      case 'diamond': return <polygon points="50,25 75,50 50,75 25,50" {...paint} />;
      case 'star': return <polygon points="50,25 56,42 74,42 60,53 65,72 50,61 35,72 40,53 26,42 44,42" {...paint} />;
      case 'hexagon': return <polygon points="25,50 37.5,28.35 62.5,28.35 75,50 62.5,71.65 37.5,71.65" {...paint} />;
      case 'plus': return <polygon points="42,25 58,25 58,42 75,42 75,58 58,58 58,75 42,75 42,58 25,58 25,42 42,42" {...paint} />;
      case 'chevron': return <polygon points="28,25 50,47 72,25 75,47 50,75 25,47" {...paint} />;
    }
  }
  return <svg className="card-face" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
    {shape()}
    <circle cx={face.markerX} cy={face.markerY} r="5" fill={face.color} stroke="#111625" strokeWidth="3" />
  </svg>;
}
const SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
const MARKERS = ['top', 'top-right', 'right', 'bottom-right', 'bottom', 'bottom-left', 'left', 'top-left'] as const;
const PALETTE = [
  ['cyan', '#63E7FF'], ['magenta', '#FF71D6'], ['green', '#8BEA7D'], ['yellow', '#FFE082'],
  ['orange', '#FFB064'], ['violet', '#B49AFF'], ['rose', '#FF8296'], ['ice', '#D9F3FF'],
] as const;
const DIAGONAL = 40 / Math.sqrt(2);
const OFFSETS = [[0, -40], [DIAGONAL, -DIAGONAL], [40, 0], [DIAGONAL, DIAGONAL],
  [0, 40], [-DIAGONAL, DIAGONAL], [-40, 0], [-DIAGONAL, -DIAGONAL]] as const;

export function faceIdentity(id: number) {
  if (!Number.isInteger(id) || id < 0 || id > 127) throw new Error('Invalid face');
  const shape = SHAPES[id % 8];
  const markerIndex = Math.floor(id / 8) % 8;
  const marker = MARKERS[markerIndex];
  const palette = PALETTE[markerIndex];
  const offset = OFFSETS[markerIndex];
  if (!shape || !marker || !palette || !offset) throw new Error('Invalid face identity');
  const fill = id < 64 ? 'solid' : 'outline';
  return { shape, fill, color: palette[1], markerX: 50 + offset[0], markerY: 50 + offset[1],
    name: `${palette[0]} ${fill} ${shape}, marker ${marker}` };
}
